const fail = (n, m) => { throw new Fail(`error: line ${n}: ${m}`) }
const NAME = /^[A-Za-z0-9_./:-]+$/
const UINT = /^(0|[1-9][0-9]*)$/

function num(n, field, s, least) {
  if (!UINT.test(s) || BigInt(s) < BigInt(least)) fail(n, `${field} must be an integer of at least ${least}`)
  return BigInt(s)
}

