  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let last = null
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const f = line.split(/\s+/)
    const d = f[0]
    if (d === 'bucket' || d === 'window') {
      const isB = d === 'bucket'
      if (f.length !== (isB ? 5 : 4)) {
        fail(n, isB ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
      }
      if (started) fail(n, 'declarations must come before the first event')
      if (!NAME.test(f[1])) fail(n, `invalid policy name ${f[1]}`)
      let p
      if (isB) {
        p = { type: 'bucket', name: f[1], cap: num(n, 'capacity', f[2], 1), refill: num(n, 'refill', f[3], 0), per: num(n, 'per', f[4], 1) }
      } else {
        p = { type: 'window', name: f[1], limit: num(n, 'limit', f[2], 0), span: num(n, 'span', f[3], 1) }
      }
      if (policies.has(p.name)) fail(n, `policy ${p.name} is declared twice`)
      policies.set(p.name, p)
    } else if (d === 'route') {
      if (f.length < 3) fail(n, 'expected route <prefix> <policy>...')
      if (started) fail(n, 'declarations must come before the first event')
      if (!NAME.test(f[1])) fail(n, `invalid route prefix ${f[1]}`)
      if (routes.has(f[1])) fail(n, `prefix ${f[1]} is routed twice`)
      for (const name of f.slice(2)) if (!policies.has(name)) fail(n, `unknown policy ${name}`)
      routes.set(f[1], f.slice(2).map((x) => policies.get(x)))
    } else if (d === 'event') {
      if (f.length !== 3) fail(n, 'expected event <tick> <key>')
      const t = num(n, 'tick', f[1], 0)
      if (!NAME.test(f[2])) fail(n, `invalid key ${f[2]}`)
      if (last !== null && t < last) fail(n, `tick ${t} is before tick ${last}`)
      last = t
      started = true
      events.push({ tick: t, key: f[2] })
    } else {
      fail(n, `unknown directive ${d}`)
    }
  })
  return { routes, events }
}

function newState(p, t) {
  return p.type === 'bucket' ? { last: t, num: p.cap * p.per } : { ticks: [] }
}
function advance(p, s, t) {
  if (p.type === 'bucket') {
    const max = p.cap * p.per
    s.num += p.refill * (t - s.last)
    if (s.num > max) s.num = max
    s.last = t
  } else {
    const lim = t - p.span
    s.ticks = s.ticks.filter((x) => x > lim)
  }
}
const allows = (p, s) => (p.type === 'bucket' ? s.num >= p.per : BigInt(s.ticks.length) < p.limit)
function record(p, s, t) {
  if (p.type === 'bucket') s.num -= p.per
  else s.ticks.push(t)
}

try {
  const { routes, events } = parse(readFileSync(0, 'utf8'))
  const states = new Map()
  const out = []
  const counts = new Map()
  let ta = 0, td = 0
  for (const e of events) {
    let best = null
    for (const [pre, ps] of routes) if (e.key.startsWith(pre) && (best === null || pre.length > best.length)) best = pre
    let denier = null
    if (best !== null) {
      const ps = routes.get(best)
      const ss = ps.map((p) => {
        const k = p.name + '\0' + e.key
        if (!states.has(k)) states.set(k, newState(p, e.tick))
        const s = states.get(k)
        advance(p, s, e.tick)
        return s
      })
      for (let i = 0; i < ps.length; i++) if (!allows(ps[i], ss[i])) { denier = ps[i].name; break }
      if (denier === null) ps.forEach((p, i) => record(p, ss[i], e.tick))
    }
    const c = counts.get(e.key) ?? { a: 0, d: 0 }
    counts.set(e.key, c)
    if (denier === null) { c.a++; ta++ } else { c.d++; td++ }
    out.push(denier === null ? `${e.tick} ${e.key} allow` : `${e.tick} ${e.key} deny ${denier}`)
  }
  if (mode === 'summary') {
    const keys = [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
    const res = keys.map((k) => `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}`)
    res.push(`total allowed=${ta} denied=${td}`)
    process.stdout.write(res.join('\n') + '\n')
  } else if (out.length) process.stdout.write(out.join('\n') + '\n')
} catch (e) {
  if (e instanceof Fail) { process.stderr.write(e.message + '\n'); process.exit(2) }
  throw e
}
